import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# Filter cancelled rows
df_active = df[~df['row_kind'].isin(['cancel', 'cancelled', 'canceled', 'void', 'voided', 'rejected'])].copy()

# Parse dates
for col in ['REPORTDATE', 'ACTSTART', 'ACTFINISH']:
    df_active[col] = pd.to_datetime(df_active[col], utc=True, errors='coerce')

df_active['repair_hours'] = pd.to_numeric(df_active['repair_hours'], errors='coerce')

# ── EDA ──────────────────────────────────────────────────────────────────────
try:
    s = df_active['repair_hours'].dropna()
    result['eda_summary'] = {
        'repair_hours': {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
    }
except Exception:
    pass

# ── SEGMENTATION ─────────────────────────────────────────────────────────────
try:
    segs = []
    seg_cols = ['WORKTYPE', 'STATUS', 'FAILURECODE']

    cm_types = {'cm','em','corrective','corrective maintenance','emergency',
                'emergency maintenance','emergency repair','breakdown',
                'breakdown maintenance','breakdown repair','reactive',
                'reactive maintenance','unplanned','unplanned maintenance',
                'unplanned breakdown','repair','fault','failure'}
    pm_types = {'pm','preventive','preventive maintenance','planned',
                'planned maintenance','pdm','predictive','predictive maintenance',
                'condition based','cbm','inspection','routine','calibration'}
    open_statuses = {'inprg','in progress','wappr','waiting on approval','appr',
                     'approved','wmatl','waiting on material','wsched',
                     'waiting to be scheduled','open','hold'}

    # WO count per segment
    for sc in seg_cols:
        grp = df_active.groupby(sc)['WONUM'].nunique().reset_index()
        grp.columns = [sc, 'val']
        grp = grp.nlargest(10, 'val')
        segs.append({
            'segment_column': sc, 'metric_column': 'WONUM',
            'aggregation': 'count', 'label': 'wo_count',
            'results': [{'name': str(r[sc]), 'value': float(r['val'])} for _, r in grp.iterrows()]
        })

    # Mean repair_hours per segment (CM/EM only, repair_hours >= 0)
    df_cm = df_active[
        df_active['WORKTYPE'].str.lower().isin(cm_types) &
        df_active['repair_hours'].notna() &
        (df_active['repair_hours'] >= 0)
    ]
    for sc in seg_cols:
        if len(df_cm) == 0:
            break
        grp = df_cm.groupby(sc)['repair_hours'].mean().reset_index()
        grp.columns = [sc, 'val']
        grp = grp.nlargest(10, 'val')
        segs.append({
            'segment_column': sc, 'metric_column': 'repair_hours',
            'aggregation': 'mean', 'label': 'mean_repair_hours_cm',
            'results': [{'name': str(r[sc]), 'value': float(r['val'])} for _, r in grp.iterrows()]
        })

    # PM share
    total_wos = df_active['WONUM'].nunique()
    pm_wos = df_active[df_active['WORKTYPE'].str.lower().isin(pm_types)]['WONUM'].nunique()
    pm_share = pm_wos / total_wos if total_wos > 0 else 0.0
    segs.append({
        'segment_column': 'WORKTYPE', 'metric_column': 'WONUM',
        'aggregation': 'ratio', 'label': 'pm_share',
        'results': [{'name': 'pm', 'value': float(pm_share)},
                    {'name': 'non_pm', 'value': float(1 - pm_share)}]
    })

    # MTTR
    mttr_sum = float(df_cm['repair_hours'].sum()) if len(df_cm) > 0 else 0.0
    mttr_n = int(df_cm['WONUM'].nunique()) if len(df_cm) > 0 else 0
    mttr_val = mttr_sum / mttr_n if mttr_n > 0 else 0.0
    segs.append({
        'segment_column': 'WORKTYPE', 'metric_column': 'repair_hours',
        'aggregation': 'ratio', 'label': 'mttr_hours',
        'results': [{'name': 'corrective', 'value': float(mttr_val)}]
    })

    # Open WOs
    open_wos = df_active[df_active['STATUS'].str.lower().isin(open_statuses)]['WONUM'].nunique()
    segs.append({
        'segment_column': 'STATUS', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': 'open_wos',
        'results': [{'name': 'open', 'value': float(open_wos)},
                    {'name': 'total', 'value': float(total_wos)}]
    })

    # FAILURECODE x WORKTYPE cross-breakdown
    cross = df_active.groupby(['FAILURECODE', 'WORKTYPE'])['WONUM'].nunique().reset_index()
    cross.columns = ['FAILURECODE', 'WORKTYPE', 'val']
    cross = cross.nlargest(10, 'val')
    segs.append({
        'segment_column': 'FAILURECODE|WORKTYPE', 'metric_column': 'WONUM',
        'aggregation': 'count', 'label': 'wo_count',
        'results': [{'name': f"{r['FAILURECODE']}|{r['WORKTYPE']}", 'value': float(r['val'])}
                    for _, r in cross.iterrows()]
    })

    result['segments'] = segs
except Exception:
    pass

# ── TRENDS ───────────────────────────────────────────────────────────────────
try:
    trends = []
    df_active['_month'] = df_active['REPORTDATE'].dt.to_period('M')

    # MoM WO count
    mo_wos = df_active.groupby('_month')['WONUM'].nunique().sort_index()
    if len(mo_wos) >= 2:
        prev, last = float(mo_wos.iloc[-2]), float(mo_wos.iloc[-1])
        pct = (last - prev) / prev * 100 if prev != 0 else 0.0
        trends.append({'column': 'WONUM', 'period': 'MoM',
                       'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
                       'pct_change': round(pct, 2), 'segment': None})

    # MoM mean repair_hours overall
    mo_rh = df_active.groupby('_month')['repair_hours'].mean().sort_index().dropna()
    if len(mo_rh) >= 2:
        prev, last = float(mo_rh.iloc[-2]), float(mo_rh.iloc[-1])
        pct = (last - prev) / prev * 100 if prev != 0 else 0.0
        trends.append({'column': 'repair_hours', 'period': 'MoM',
                       'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
                       'pct_change': round(pct, 2), 'segment': None})

    # MoM mean repair_hours per WORKTYPE
    for wt in df_active['WORKTYPE'].dropna().unique():
        sub = df_active[df_active['WORKTYPE'] == wt].groupby('_month')['repair_hours'].mean().sort_index().dropna()
        if len(sub) >= 2 and float(sub.iloc[-2]) != 0:
            prev, last = float(sub.iloc[-2]), float(sub.iloc[-1])
            pct = (last - prev) / prev * 100
            trends.append({'column': 'repair_hours', 'period': 'MoM',
                           'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
                           'pct_change': round(pct, 2), 'segment': str(wt)})

    result['trends'] = trends
except Exception:
    pass

# ── ANOMALIES ────────────────────────────────────────────────────────────────
try:
    anomalies = []
    s = df_active['repair_hours'].dropna()
    if len(s) >= 5 and s.nunique() >= 5:
        skew = float(s.skew())
        shift = max(0.0, -float(s.min()))
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = lo_t, hi_t
        flagged = s_t[(s_t < lo_t) | (s_t > hi_t)]
        flag_rate = len(flagged) / len(s)
        if flag_rate > 0.05:
            anomalies.append({
                'column': 'repair_hours', 'row_index': None, 'value': None,
                'expected_range': f"[{lo_orig:.2f}, {hi_orig:.2f}]",
                'severity': 'low',
                'explanation': 'repair_hours is heavy-tailed; natural spread, not flagged individually'
            })
        else:
            cap = 25
            for idx in flagged.index[:cap]:
                raw = float(df_active.loc[idx, 'repair_hours'])
                sv = float(s_t.loc[idx])
                if sv > q3 + 5 * iqr or sv < q1 - 5 * iqr:
                    sev = 'critical'
                elif sv > q3 + 4 * iqr or sv < q1 - 4 * iqr:
                    sev = 'high'
                else:
                    sev = 'medium'
                anomalies.append({
                    'column': 'repair_hours', 'row_index': int(idx), 'value': raw,
                    'expected_range': f"[{lo_orig:.2f}, {hi_orig:.2f}]",
                    'severity': sev,
                    'explanation': f"repair_hours value {raw:.2f} lies outside expected range [{lo_orig:.2f}, {hi_orig:.2f}]"
                })
                cap -= 1
                if cap <= 0:
                    break
    result['anomalies'] = anomalies
except Exception:
    pass

result['assumptions'] = [
    "Cancelled work orders (row_kind cancel/void/etc.) excluded from all KPIs.",
    "MTTR uses only CM/EM work types with repair_hours >= 0; repair_hours column used as-is.",
    "PM share = distinct PM WOs / all distinct non-cancelled WOs.",
    "Trends use REPORTDATE month; MoM compares the two most recent calendar months.",
    "response_hours (ACTSTART-REPORTDATE) excluded — not a schema column; repair_hours used instead."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'ASSETNUM' in df.columns:
        _vc = df['ASSETNUM'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['ASSETNUM'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'WORKTYPE' in df.columns:
        _vc = df['WORKTYPE'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['WORKTYPE'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'STATUS' in df.columns:
        _vc = df['STATUS'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['STATUS'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'FAILURECODE' in df.columns:
        _vc = df['FAILURECODE'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['FAILURECODE'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'REPORTEDBY' in df.columns:
        _vc = df['REPORTEDBY'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['REPORTEDBY'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass
print(json.dumps(result, default=str))

